_NONE = 0;   // legacy: use parent_id/after_id\n  TOP           = 1;   // above target, same parent\n  BOTTOM        = 2;   // below target, same parent\n  LEFT          = 3;   // new/existing column to the left of target\n  RIGHT         = 4;   // new/existing column to the right of target\n  INNER         = 5;   // inside target, as last child\n  REPLACE       = 6;   // replace target (children may be inherited)\n  INNER_FIRST   = 7;   // inside target, as first child\n}\n\n// Insert a block into the block tree.\n// New writers set target_id + position; parent_id/after_id remain for\n// decoding pre-position history (replayed as root appends).\nmessage BlockAdd {\n  string   parent_id = 1;   // legacy: parent block id (\"\" = root level)\n  string   after_id  = 2;   // legacy: insert after this sibling (\"\" = first)\n  Block    block     = 3;\n  string   target_id = 4;   // block the position is relative to (\"\" = root)\n  Position position  = 5;\n}\n\n// Remove a block and its descendants.\nmessage BlockRemove {\n  string block_id = 1;\n}\n\n// Replace a block's content.\nmessage BlockUpdate {\n  string       block_id = 1;\n  BlockContent content  = 2;\n}\n\n// Move a block (and its subtree) to a new position.\nmessage BlockMove {\n  string   block_id      = 1;\n  string   new_parent_id = 2;  // legacy addressing\n  string   after_id      = 3;  // legacy addressing\n  string   target_id     = 4;\n  Position position      = 5;\n}\n\n\n// ── Layer 2: Sync Protocol ───────────────────────────────────────\n//\n// Typed messages for DAG exchange between peers. Pull-based:\n// a peer advertises its heads, the other responds with what's\n// missing. Every message is an Envelope with a typed payload.\n//\n// The transport is Rivet actor actions over HTTP. Each object\n// actor is a sync peer — globally addressable, durable,\n// wakes on demand.\n\nmessage Envelope {\n  string from_id   = 1;    // sender actor/object id\n  string to_id     = 2;    // recipient actor/object id\n  int64  timestamp = 3;\n\n  oneof message {\n    // Sync: DAG exchange\n    HeadAdvertise   head_advertise   = 10;\n    HeadRequest     head_request     = 11;\n    ChangePush      change_push      = 12;\n    ChangeRequest   change_request   = 13;\n\n    // Subscriptions: live updates\n    ObjectSubscribe object_subscribe = 20;\n    ObjectEvent     object_event     = 21;\n\n    // Application: free-form IPC between objects\n    AppMessage      app_message      = 30;\n  }\n}\n\n// \"Here are my heads for this object.\"\n// Sent on connection or periodically. Receiver compares against\n// its own heads to determine what's missing on either side.\nmessage HeadAdvertise {\n  string object_id       = 1;\n  repeated bytes head_ids = 2;  // content-addressed change ids\n}\n\n// \"Send me changes between these known ancestors and these heads.\"\n// Response is a ChangePush.\nmessage HeadRequest {\n  string object_id        = 1;\n  repeated bytes known_ids  = 2;  // changes I already have\n  repeated bytes target_ids = 3;  // heads I want to reach\n}\n\n// \"Here are changes you're missing.\"\n// Changes are topologically sorted — the receiver can apply them\n// incrementally without needing the full DAG upfront.\nmessage ChangePush {\n  string object_id       = 1;\n  repeated Change changes = 2;  // topologically sorted\n}\n\n// \"Send me these specific changes by hash.\"\n// Fallback when HeadRequest can't express the need.\nmessage ChangeRequest {\n  string object_id         = 1;\n  repeated bytes change_ids = 2;\n}\n\n// \"Notify me when this object changes.\"\nmessage ObjectSubscribe {\n  string object_id = 1;\n}\n\n// \"This object changed.\"\nmessage ObjectEvent {\n  string object_id           = 1;\n  repeated bytes new_head_ids = 2;\n  repeated Change changes     = 3;  // inline, saves a round-trip\n}\n\n// Free-form application message. The old Envelope behavior\n// for non-sync IPC between objects.\nmessage AppMessage {\n  string action  = 1;\n  bytes  payload = 2;\n}\n\n\n// ── Layer 3: Computed State ──────────────────────────────────────\n//\n// Derived by replaying the DAG. Never the source of truth.\n// ObjectSnapshot can be embedded in a Change as a checkpoint\n// to speed up replay (skip everything before the snapshot).\n\nmessage ObjectSnapshot {\n  string id       = 1;\n  string type_key = 2;\n  map<string, Value> fields = 3;\n  // Deprecated: content moved to primary block\n  bytes content = 4;\n  repeated Block blocks = 5;\n  bool   deleted    = 6;\n  int64  created_at = 7;\n  int64  updated_at = 8;\n}\n\n// Lightweight reference for listings. No content, no fields.\nmessage ObjectRef {\n  string id        = 1;\n  string type_key  = 2;\n  int64  created_at = 3;\n  int64  updated_at = 4;\n}\n\n\n// ── Blocks ───────────────────────────────────────────────────────\n//\n// Objects contain a tree of blocks. A page's blocks are paragraphs,\n// headings, lists. A database's blocks are records. Composable.\n\nmessage Block {\n  string id = 1;\n  repeated string children_ids = 2;\n  BlockContent content = 3;\n  ValueMap fields = 4;            // per-block config, e.g. fields[\"width\"] on columns\n  BlockAlign align = 5;\n  string background_color = 6;\n}\n\nenum BlockAlign {\n  ALIGN_LEFT    = 0;\n  ALIGN_CENTER  = 1;\n  ALIGN_RIGHT   = 2;\n  ALIGN_JUSTIFY = 3;\n}\n\nmessage BlockContent {\n  oneof content {\n    TextContent        text         = 1;\n    CustomContent      custom       = 2;\n    LayoutContent      layout       = 3;\n    TableContent       table        = 4;\n    TableColumnContent table_column = 5;\n    TableRowContent    table_row    = 6;\n  }\n}\n\n// Table trio (Anytype-faithful). A table block's children are exactly two\n// layouts: one TABLE_COLUMNS (holding TableColumn marker blocks, whose\n// order + fields[\"width\"] define the columns) and one TABLE_ROWS (holding\n// TableRow blocks). A row's children are ordinary text blocks whose id is\n// \"<rowId>-<colId>\" — sparse rows are legal; a missing cell renders empty.\nmessage TableContent {}\nmessage TableColumnContent {}\nmessage TableRowContent {\n  bool is_header = 1;\n}\n\n// Structural block with no visual content of its own — it only shapes\n// children_ids. ROW/COLUMN pairs are created and destroyed automatically\n// by LEFT/RIGHT block placement + the normalize pass, never by hand.\nmessage LayoutContent {\n  LayoutStyle style = 1;\n}\n\nenum LayoutStyle {\n  ROW           = 0;\n  COLUMN        = 1;\n  DIV           = 2;\n  HEADER        = 3;\n  TABLE_ROWS    = 4;  // container for TableRow blocks\n  TABLE_COLUMNS = 5;  // container for TableColumn blocks\n}\n\n// Program-defined block content. The OS stores, syncs, and\n// content-addresses it without interpreting the payload.\n// Programs encode their domain-specific block data into `data`\n// and declare the type via `content_type`. The `meta` map lets\n// the OS display a fallback (title, description) for blocks\n// whose type it doesn't understand.\nmessage CustomContent {\n  string content_type          = 1;  // e.g. \"image\", \"table\", \"embed\"\n  bytes  data                  = 2;  // program-encoded payload\n  map<string, string> meta     = 3;  // fallback display metadata\n}\n\nmessage TextContent {\n  string    text  = 1;\n  TextStyle style = 2;\n  repeated Mark marks = 3;   // ranged inline formatting\n  bool      checked = 4;     // CHECKBOX / TOGGLE state\n  string    color = 5;       // whole-block text color\n}\n\n// Inline formatting over a character range [from, to) of TextContent.text.\n// param carries the mark's payload: url for LINK, color name for\n// TEXT_COLOR/BACKGROUND_COLOR, object id for MENTION/OBJECT.\nmessage Mark {\n  int32    from  = 1;\n  int32    to    = 2;\n  MarkType type  = 3;\n  string   param = 4;\n}\n\nenum MarkType {\n  BOLD             = 0;\n  ITALIC           = 1;\n  STRIKETHROUGH    = 2;\n  UNDERLINE        = 3;\n  INLINE_CODE      = 4;\n  LINK             = 5;\n  TEXT_COLOR       = 6;\n  BACKGROUND_COLOR = 7;\n  MENTION          = 8;\n  OBJECT_MARK      = 9;\n}\n\nenum TextStyle {\n  PARAGRAPH   = 0;\n  HEADER1     = 1;\n  HEADER2     = 2;\n  HEADER3     = 3;\n  QUOTE       = 4;\n  CODE        = 5;\n  BULLET      = 6;\n  NUMBERED    = 7;\n  CHECKBOX    = 8;\n  TITLE       = 9;\n  TOGGLE      = 10;\n  CALLOUT     = 11;\n  DESCRIPTION = 12;\n}\n\n\n// ── Values ───────────────────────────────────────────────────────\n//\n// Typed values for fields. The oneof enforces type safety at the\n// protobuf level — no stringly-typed maps.\n//\n// Value is recursive: ValueMap and ValueList contain Values,\n// so programs can express arbitrarily nested structures without\n// modifying glon.proto. A browser stores cookie jars as nested\n// maps. A spreadsheet stores cell metadata as typed lists.\n// Glon carries it all through the same Change DAG.\n\nmessage Value {\n  oneof kind {\n    string     string_value  = 1;\n    int64      int_value     = 2;\n    double     float_value   = 3;\n    bool       bool_value    = 4;\n    bytes      bytes_value   = 5;\n    StringList list_value    = 6;\n    ValueMap   map_value     = 7;   // nested key-value\n    ValueList  values_value  = 8;   // heterogeneous typed list\n    ObjectLink link_value    = 9;   // typed link to another object\n  }\n}\n\n// A typed link from this object to another.\n// Links are field values — they participate in FieldSet/FieldDelete like any\n// other Value kind. A Task's \"assignee\" field is a link to a Person object.\n// Links in a ValueList express one-to-many (a Project's \"tasks\" field).\nmessage ObjectLink {\n  string target_id    = 1;  // the linked object's UUID\n  string relation_key = 2;  // e.g. \"assignee\", \"parent\", \"blocks\"\n}\n\nmessage StringList {\n  repeated string values = 1;\n}\n\n// Recursive map: string keys to typed Values.\nmessage ValueMap {\n  map<string, Value> entries = 1;\n}\n\n// Recursive list: ordered sequence of typed Values.\nmessage ValueList {\n  repeated Value items = 1;\n}\n\n\n// ── Transport Layer ──────────────────────────────────────────────\n//\n// Transport-agnostic envelope for moving opaque bytes between\n// Glon instances. Transports carry Envelope bytes; the router\n// dispatches by content_type. No gossip, no consensus — just\n// signed payloads moved over whatever pipe is available.\n\nmessage TransportEnvelope {\n  string content_type = 1;        // e.g. \"glon/change-bundle\", \"glon/text\"\n  bytes payload = 2;              // content-type-specific bytes\n  bytes sender_pubkey = 3;        // optional convenience for receiver lookup\n  map<string, string> metadata = 4;\n}\n\n// A bundle of Changes for import. No id, no hash — the Changes\n// inside are individually content-addressed. The bundle is a\n// transient wrapper that ceases to exist after dispatch.\nmessage ChangeBundle {\n  repeated bytes changes = 1;     // each is a serialized Change proto\n}\n\n// A lightweight text message for agent-to-agent chat.\n// Carried in TransportEnvelope with content_type=\"glon/text\".\nmessage TextMessage {\n  string text = 1;\n}\n";
